function parseFlags(argv) {
  const flags = { _: [] };

  for (const arg of argv) {
    if (!arg.startsWith('--')) {
      flags._.push(arg);
      continue;
    }

    const body = arg.slice(2);
    const eq = body.indexOf('=');

    if (eq === -1) {
      flags[body] = true;
    } else {
      flags[body.slice(0, eq)] = body.slice(eq + 1);
    }
  }

  return flags;
}

module.exports = { parseFlags };

const test = require('node:test');
const assert = require('node:assert/strict');

const { parseFlags } = require('../src/flags');

test('--name=value sets the flag to the string value', () => {
  assert.deepEqual(parseFlags(['--out=x']), { _: [], out: 'x' });
});

test('--name without = sets the flag to true', () => {
  assert.deepEqual(parseFlags(['--verbose']), { _: [], verbose: true });
});

test('non-flag arguments are collected in order under _', () => {
  assert.deepEqual(parseFlags(['a', '--verbose', 'b']), {
    _: ['a', 'b'],
    verbose: true,
  });
});

test('empty argv returns only an empty _', () => {
  assert.deepEqual(parseFlags([]), { _: [] });
});
